		label: string,
		action: BranchMenuAction,
		enabled: boolean,
		accelerator?: string
	): MenuItemConstructorOptions => ({
		label,
		enabled,
		accelerator,
		click: () => sendBranchAction(action)
	});

	return [
		branchAction('New Branch…', 'newBranch', s.hasRepo, 'Shift+CmdOrCtrl+N'),
		{ type: 'separator' },
		branchAction(
			`Update from ${s.defaultBranch}`,
			'updateFromDefault',
			s.hasRepo && !s.onDefaultBranch,
