diff --git a/apps/desktop/src/renderer/src/lib/components/RepositoryMenu.svelte b/apps/desktop/src/renderer/src/lib/components/RepositoryMenu.svelte
new file mode 100644
--- /dev/null
+++ b/apps/desktop/src/renderer/src/lib/components/RepositoryMenu.svelte
@@ -0,0 +1,106 @@
+<script lang="ts">
+	// Headless glue between the native "Repository" menu (built in the main
+	// process) and the renderer — mirrors BranchMenu. Renders nothing: it pushes
+	// the current enablement/labels up so the native menu reflects the active repo,
+	// and runs the matching store flow when an item is chosen. Mounted once at the
+	// app root.
+	import { onMount } from 'svelte';
+	import { confirmDelete } from './ui/confirm-delete-dialog';
+	import {
+		actions,
+		app,
+		effectiveEditor,
+		effectiveTerminal,
+		EDITOR_LABELS,
+		TERMINAL_LABELS
+	} from '$lib/store.svelte';
+	import type { RepositoryMenuAction, RepositoryMenuState } from '@shared/types';
+
+	function revealLabel(): string {
+		return app.platform === 'win32'
+			? 'Show in Explorer'
+			: app.platform === 'linux'
+				? 'Show in File Manager'
+				: 'Show in Finder';
+	}
+
+	// Keep the native Repository menu's enabled state + dynamic labels in sync,
+	// deduped so unrelated reactive churn doesn't rebuild the OS menu.
+	let lastSent = '';
+	$effect(() => {
+		const repo = app.activeRepo;
+		const editor = effectiveEditor();
+		const terminal = effectiveTerminal();
+		const state: RepositoryMenuState = {
+			hasRepo: !!repo,
+			hasRemote: !!app.pushStatus?.hasRemote,
+			hasGithub: !!repo?.githubOwner && !!repo?.githubRepo,
+			editorLabel: editor ? EDITOR_LABELS[editor] : null,
+			terminalLabel: terminal ? TERMINAL_LABELS[terminal] : null,
+			revealLabel: revealLabel()
+		};
+		const serialized = JSON.stringify(state);
+		if (serialized === lastSent) return;
+		lastSent = serialized;
+		window.api.menu.setRepositoryState(state);
+	});
+
+	// Mirror GitHub Desktop's remove dialog: warning, the repo's path, and an
+	// opt-in to also move the folder to the OS trash (same as the repo picker).
+	function requestRemove(): void {
+		const repo = app.activeRepo;
+		if (!repo) return;
+		const trashLabel = app.platform === 'win32' ? 'Recycle Bin' : 'Trash';
+		confirmDelete({
+			title: 'Remove repository',
+			icon: 'warning',
+			description: `Are you sure you want to remove the repository "${repo.name}" from super-review?`,
+			details: {
+				caption: 'The repository will be removed from super-review:',
+				value: repo.path
+			},
+			checkbox: { label: `Also move this repository to ${trashLabel}`, default: false },
+			confirm: { text: 'Remove' },
+			onConfirm: async ({ checked }) => {
+				await actions.removeRepo(repo.id, checked);
+			}
+		});
+	}
+
+	function handle(action: RepositoryMenuAction): void {
+		switch (action) {
+			case 'push':
+				void actions.push();
+				return;
+			case 'pull':
+				void actions.pull();
+				return;
+			case 'fetch':
+				void actions.fetchAndRefresh();
+				return;
+			case 'remove':
+				requestRemove();
+				return;
+			case 'viewOnGithub':
+				void actions.openRepoOnGithub();
+				return;
+			case 'openInTerminal':
+				void actions.openInTerminal();
+				return;
+			case 'showInFinder':
+				void actions.openRepoInFileManager();
+				return;
+			case 'openInEditor':
+				void actions.openInEditor();
+				return;
+			case 'createIssue':
+				void actions.createIssueOnGithub();
+				return;
+			case 'settings':
+				actions.openRepoSettingsDialog();
+				return;
+		}
+	}
+
+	onMount(() => window.api.events.onRepositoryMenuAction(handle));
+</script>

diff --git a/apps/desktop/src/renderer/src/lib/components/RepositorySettingsDialog.svelte b/apps/desktop/src/renderer/src/lib/components/RepositorySettingsDialog.svelte
new file mode 100644
--- /dev/null
+++ b/apps/desktop/src/renderer/src/lib/components/RepositorySettingsDialog.svelte
@@ -0,0 +1,102 @@
+<script lang="ts">
+	import { GitFork } from 'lucide-svelte';
+	import { Button } from './ui/button';
+	import SettingsShell from './SettingsShell.svelte';
+	import ForkUseChoice from './ForkUseChoice.svelte';
+	import { actions, app } from '$lib/store.svelte';
+
+	let open = $derived(app.repoSettingsDialogOpen);
+	let activeTab = $state('fork');
+	const TABS = [{ id: 'fork', label: 'Fork Behavior', icon: GitFork }];
+
+	// Parent resolved from the GitHub API when the dialog opens — needed even in
+	// "own purposes" mode, where the upstream metadata is cleared. undefined =
+	// still loading; null = not a fork.
+	let parent = $state<{ owner: string; repo: string } | null | undefined>(undefined);
+	let use = $state<'parent' | 'self'>('parent');
+	let saving = $state(false);
+
+	// (Re)load when the dialog opens for the active repo. Default the radio from
+	// the current metadata (upstream present = currently contributing to parent).
+	let loadedFor: string | null = null;
+	$effect(() => {
+		if (!open) {
+			loadedFor = null;
+			return;
+		}
+		const repo = app.activeRepo;
+		if (!repo || loadedFor === repo.id) return;
+		loadedFor = repo.id;
+		activeTab = 'fork';
+		use = repo.upstreamOwner && repo.upstreamRepo ? 'parent' : 'self';
+		parent = undefined;
+		void window.api.github.getRepoParent(repo.id).then((p) => {
+			if (app.repoSettingsDialogOpen && app.activeRepo?.id === repo.id) parent = p;
+		});
+	});
+
+	const parentLabel = $derived(parent ? `${parent.owner}/${parent.repo}` : null);
+	const isFork = $derived(parent != null);
+
+	async function save(): Promise<void> {
+		saving = true;
+		await actions.setForkBehavior(use === 'parent');
+		saving = false;
+		actions.closeRepoSettingsDialog();
+	}
+</script>
+
+<SettingsShell
+	bind:open
+	title="Repository Settings"
+	tabs={TABS}
+	bind:activeTab
+	onClose={() => actions.closeRepoSettingsDialog()}
+>
+	{#snippet content(_tab)}
+		<section class="space-y-4">
+			{#if parent === undefined}
+				<p class="text-sm text-muted-foreground">Checking fork status…</p>
+			{:else if !isFork}
+				<p class="text-sm text-muted-foreground">
+					This repository isn't a fork, so there's nothing to configure here.
+				</p>
+			{:else}
+				<h3 class="text-base font-semibold">I'll be using this fork…</h3>
+				<ForkUseChoice bind:value={use} {parentLabel} idPrefix="repo-settings" disabled={saving} />
+				<ul class="space-y-1.5 text-xs text-muted-foreground">
+					{#if use === 'parent'}
+						<li>
+							Pull requests targeting
+							<span class="font-medium text-foreground">{parentLabel}</span> will be shown in the pull
+							request list.
+						</li>
+						<li>
+							"Create Issue on GitHub" will create issues in
+							<span class="font-medium text-foreground">{parentLabel}</span>.
+						</li>
+						<li>
+							"View on GitHub" will open
+							<span class="font-medium text-foreground">{parentLabel}</span> in the browser.
+						</li>
+					{:else}
+						<li>Pull requests and "Create Issue on GitHub" will target your own fork.</li>
+						<li>"View on GitHub" will open your fork in the browser.</li>
+					{/if}
+				</ul>
+			{/if}
+		</section>
+	{/snippet}
+
+	{#snippet footer()}
+		<Button
+			variant="secondary"
+			size="sm"
+			onclick={() => actions.closeRepoSettingsDialog()}
+			disabled={saving}
+		>
+			Cancel
+		</Button>
+		<Button size="sm" onclick={save} disabled={saving || !isFork}>Save</Button>
+	{/snippet}
+</SettingsShell>

diff --git a/apps/desktop/src/renderer/src/lib/components/SettingsShell.svelte b/apps/desktop/src/renderer/src/lib/components/SettingsShell.svelte
new file mode 100644
--- /dev/null
+++ b/apps/desktop/src/renderer/src/lib/components/SettingsShell.svelte
@@ -0,0 +1,84 @@
+<script lang="ts">
+	// Reusable settings-dialog shell: a titled dialog with a left tab nav and a
+	// scrollable content pane, plus an optional footer. Shared by the app Settings
+	// dialog and the per-repo Repository Settings dialog so the layout lives in one
+	// place. The owner supplies the tabs, the active tab (bindable), and snippets
+	// for the content (rendered with the active tab id) and footer.
+	import type { Snippet } from 'svelte';
+	import { Icon } from 'lucide-svelte';
+	import * as Dialog from './ui/dialog';
+	import { cn } from '$lib/utils';
+
+	// lucide-svelte icons are SvelteComponentTyped classes; `typeof Icon` (the base
+	// icon class) is the shared constructor type every icon is assignable to.
+	type Tab = { id: string; label: string; icon: typeof Icon };
+
+	let {
+		open = $bindable(false),
+		title,
+		tabs,
+		activeTab = $bindable(),
+		onClose,
+		content,
+		footer
+	}: {
+		open: boolean;
+		title: string;
+		tabs: Tab[];
+		activeTab: string;
+		onClose?: () => void;
+		content: Snippet<[string]>;
+		footer?: Snippet;
+	} = $props();
+</script>
+
+<Dialog.Root
+	bind:open
+	onOpenChange={(o) => {
+		if (!o) onClose?.();
+	}}
+>
+	<Dialog.Content
+		class="w-[720px] !max-w-[calc(100%-2rem)] !gap-0 overflow-hidden !p-0"
+		showCloseButton={true}
+	>
+		<Dialog.Header class="border-b border-border px-4 py-3">
+			<Dialog.Title class="text-base">{title}</Dialog.Title>
+		</Dialog.Header>
+
+		<div class="flex h-[480px] min-h-0">
+			<!-- Left nav -->
+			<nav class="w-48 shrink-0 border-r border-border bg-card/30 p-2">
+				{#each tabs as tab (tab.id)}
+					{@const Icon = tab.icon}
+					<button
+						type="button"
+						class={cn(
+							'flex w-full items-center gap-2 rounded-md px-2.5 py-1.5 text-left text-sm',
+							activeTab === tab.id
+								? 'bg-muted text-foreground'
+								: 'text-muted-foreground hover:bg-muted/50 hover:text-foreground'
+						)}
+						onclick={() => (activeTab = tab.id)}
+					>
+						<Icon class="size-4" />
+						{tab.label}
+					</button>
+				{/each}
+			</nav>
+
+			<!-- Content panel -->
+			<div class="min-w-0 flex-1 overflow-y-auto p-5">
+				{@render content(activeTab)}
+			</div>
+		</div>
+
+		{#if footer}
+			<footer
+				class="flex items-center justify-end gap-2 border-t border-border bg-muted/30 px-4 py-3"
+			>
+				{@render footer()}
+			</footer>
+		{/if}
+	</Dialog.Content>
+</Dialog.Root>
